    $saved = db()->query("SELECT s.Id_services,s.title,s.price,s.description,s.location,c.name AS category,u.first_name,u.name AS last_name,m.file_path AS image,(SELECT COUNT(*) FROM Favorites f WHERE f.Id_services=s.Id_services) AS likes,(SELECT ROUND(AVG(r.rating),1) FROM Reviews r JOIN Bookings b ON b.Id_bookings=r.Id_bookings WHERE b.Id_services=s.Id_services) AS rating,(SELECT COUNT(*) FROM Reviews r JOIN Bookings b ON b.Id_bookings=r.Id_bookings WHERE b.Id_services=s.Id_services) AS reviews FROM Services s JOIN Categories c ON c.Id_categories=s.Id_categories JOIN Users u ON u.Id_users=s.Id_users LEFT JOIN Media m ON m.Id_services=s.Id_services WHERE s.status='active' ORDER BY s.Id_services DESC")->fetchAll();
